import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1+n]))
    if n != len(a):
        return
    min_val = min(a)
    last_idx = -1
    min_dist = float('inf')
    for i in range(n):
        if a[i] == min_val:
            if last_idx != -1:
                min_dist = min(min_dist, i - last_idx)
            last_idx = i
    print(min_dist)

if __name__ == "__main__":
    main()
"}

