import sys
import math

def get_divisors(g):
    """Get all divisors of g."""
    divisors = set()
    for i in range(1, int(math.isqrt(g)) + 1):
        if g % i == 0:
            divisors.add(i)
            divisors.add(g // i)
    return sorted(divisors)

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    a = int(next(it))
    b = int(next(it))
    n = int(next(it))
    divisors = get_divisors(math.gcd(a, b))

    for _ in range(n):
        low = int(next(it))
        high = int(next(it))
        # Find max divisor <= high and >= low
        left, right = 0, len(divisors) - 1
        ans = -1
        while left <= right:
            mid = (left + right) // 2
            d = divisors[mid]
            if d <= high:
                ans = d
                left = mid + 1
            else:
                right = mid - 1
        if ans >= low:
            print(ans)
        else:
            print(-1)

if __name__ == "__main__":
    solve()
"}

