a, b = map(int, input().split())
n = int(input())
queries = [tuple(map(int, input().split())) for _ in range(n)]

gcd_val = math.gcd(a, b)
# Generate divisors of gcd_val
def get_divisors(x):
    divisors = set()
    for i in range(1, int(x**0.5)+1):
        if x % i == 0:
            divisors.add(i)
            divisors.add(x//i)
    return sorted(divisors, reverse=True)

divisors = get_divisors(gcd_val)

for low, high in queries:
    ans = -1
    for d in divisors:
        if low <= d <= high:
            ans = d
            break
    print(ans)
"}

