s = input().strip()
chars = [c for c in s]

for i in range(len(chars) - 1):
    if chars[i] == chars[i+1]:
        # Find a character to replace chars[i+1]
        new_char = 'a'
        while new_char == chars[i] or (i+2 < len(chars) and new_char == chars[i+2]):
            if new_char == 'z':
                # If all fail, just pick a different character
                new_char = 'a' if chars[i] != 'a' else 'b'
            else:
                new_char = chr(ord(new_char) + 1)
        chars[i+1] = new_char

