{"code": "
import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    t = int(data[idx]); idx += 1

    for _ in range(t):
        n = int(data[idx]); idx += 1
        a = list(map(int, data[idx:idx+n])); idx += n

        # Check if we can reduce to 1 element
        can_reduce = True
        i = 0
        # Try to remove elements from left to right
        while i < len(a) - 1:
            if a[i] < a[i+1]:
                # We can remove either a[i] or a[i+1]
                if a[i] < a[i+1]:
                    # Remove a[i] (keep a[i+1])
                    a.pop(i)
                else:
                    # Remove a[i+1] (keep a[i])
                    a.pop(i+1)
            else:
                # Cannot remove anything at this point
                can_reduce = False
                break

