import sys

def solve():
    word = sys.stdin.readline().strip()
    n = len(word)
    if n == 0:
        return
    vowels = set('aeiou')
    is_consonant = [ch not in vowels for ch in word]

    # Check if whole word is valid
    valid = True
    for i in range(n - 2):
        if is_consonant[i] and is_consonant[i+1] and is_consonant[i+2]:
            if word[i] != word[i+1] or word[i] != word[i+2]:
                valid = False
                break
    if valid:
        print(word)
        return

    # DP to find minimal number of splits
    INF = 10**9
    dp = [INF] * (n + 1)
    dp[0] = 0
    prev = [-1] * (n + 1)

    for i in range(1, n + 1):
        # Try all possible j (split positions)
        for j in range(i - 1, -1, -1):
            # Check substring s[j..i-1]
            is_valid = True
            for k in range(j, i - 2):
                # Check window [k, k+1, k+2]
                # Actually we need to check if all three are consonant and not all equal
                # and k+2 <= i-1
                if k + 2 >= i:
                    break
                if is_consonant[k] and is_consonant[k+1] and is_consonant[k+2]:
                    if word[k] != word[k+1] or word[k] != word[k+2]:
                        is_valid = False
                        break
            if is_valid:
                if dp[j] + 1 < dp[i]:
                    dp[i] = dp[j] + 1
                    prev[i] = j

    # Reconstruct splits
    res = []
    cur = n
    while cur > 0:
        j = prev[cur]
        word_part = word[j:cur]
        res.append(word_part)
        cur = j
    res.reverse()
    print(' '.join(res))

if __name__ == '__main__':
    solve()
