import math

def read_input():
    n = int(input())
    triangles = []
    for _ in range(n):
        x1, y1, x2, y2, x3, y3 = map(int, input().split())
        triangles.append((x1, y1, x2, y2, x3, y3))
    return n, triangles

def perimeter_point(p1, p2):
    return math.sqrt((p2[0] - p1[0])**2 + (p2[1] - p1[1])**2)

def edge_length(p1, p2):
    return math.sqrt((p2[0] - p1[0])**2 + (p2[1] - p1[1])**2)

def orientation(p, q, r):
    val = (q[0] - p[0]) * (r[1] - p[1]) - (q[1] - p[1]) * (r[0] - p[0])
    if abs(val) < 1e-9:
        return 0  # colinear
    return 1 if val > 0 else 2

def on_segment(p, q, r):
    if (min(p[0], r[0]) - 1e-9 <= q[0] <= max(p[0], r[0]) + 1e-9 and
        min(p[1], r[1]) - 1e-9 <= q[1] <= max(p[1], r[1]) + 1e-9):
        return True
    return False

def segments_intersect(p1, q1, p2, q2):
    o1 = orientation(p1, q1, p2)
    o2 = orientation(p1, q1, q2)

    o3 = orientation(p2, q2, p1)
    o4 = orientation(p2, q2, q1)

    if o1 != o2 and o3 != o4:
        return True

    if o1 == 0 and on_segment(p1, p2, q1):
        return True
    if o2 == 0 and on_segment(p1, q2, q1):
        return True
    if o3 == 0 and on_segment(p2, p1, q2):
        return True
    if o4 == 0 and on_segment(p2, q1, q2):
        return True

    return False

def solve():
    n, triangles = read_input()

    total_perimeter = 0

    for i in range(n):
        p1, q1, p2, q2, p3, q3 = triangles[i]

        # Check if edge 1-2 is intersected
        intersected = False
        for j in range(n):
            if i == j:
                continue
            p4, q4, p5, q5, p6, q6 = triangles[j]

            # Check if any edge of triangle j intersects with edge 1-2
            if segments_intersect((p1, q1), (p2, q2), (p4, q4), (p5, q5)):
                intersected = True
                break
            if segments_intersect((p1, q1), (p2, q2), (p5, q5), (p6, q6)):
                intersected = True
                break
            if segments_intersect((p1, q1), (p2, q2), (p6, q6), (p4, q4)):
                intersected = True
                break

        if not intersected:
            total_perimeter += edge_length((p1, q1), (p2, q2))

        # Check if edge 2-3 is intersected
        intersected = False
        for j in range(n):
            if i == j:
                continue
            p4, q4, p5, q5, p6, q6 = triangles[j]

            # Check if any edge of triangle j intersects with edge 2-3
            if segments_intersect((p2, q2), (p3, q3), (p4, q4), (p5, q5)):
                intersected = True
                break
            if segments_intersect((p2, q2), (p3, q3), (p5, q5), (p6, q6)):
                intersected = True
