import math

def read_input():
    n = int(input())
    triangles = []
    for _ in range(n):
        x1, y1, x2, y2, x3, y3 = map(int, input().split())
        triangles.append((x1, y1, x2, y2, x3, y3))
    return n, triangles

def edge_length(p1, p2):
    return math.sqrt((p2[0] - p1[0])**2 + (p2[1] - p1[1])**2)

def orientation(p, q, r):
    val = (q[0] - p[0]) * (r[1] - p[1]) - (q[1] - p[1]) * (r[0] - p[0])
    if abs(val) < 1e-9:
        return 0  # colinear
    return 1 if val > 0 else 2

def on_segment(p, q, r):
    if (min(p[0], r[0]) - 1e-9 <= q[0] <= max(p[0], r[0]) + 1e-9 and
        min(p[1], r[1]) - 1e-9 <= q[1] <= max(p[1], r[1]) + 1e-9):
        return True
    return False

def segments_intersect(p1, q1, p2, q2):
    o1 = orientation(p1, q1, p2)
    o2 = orientation(p1, q1, q2)

    o3 = orientation(p2, q2, p1)
    o4 = orientation(p2, q2, q1)

    if o1 != o2 and o3 != o4:
        return True

    if o1 == 0 and on_segment(p1, p2, q1):
        return True
    if o2 == 0 and on_segment(p1, q2, q1):
        return True
    if o3 == 0 and on_segment(p2, p1, q2):
        return True
    if o4 == 0 and on_segment(p2, q1, q2):
        return True

    return False

def is_point_inside_triangle(p, t):
    # t = (p1, q1, p2, q2, p3, q3)
    p1, q1, p2, q2, p3, q3 = t

    o1 = orientation(p, p1, p2)
    o2 = orientation(p, p2, p3)
    o3 = orientation(p, p3, p1)

    if (o1 >= 0 and o2 >= 0 and o3 >= 0) or (o1 <= 0 and o2 <= 0 and o3 <= 0):
        return True

    # If the point is on an edge
    if o1 == 0:
        return on_segment(p, p1, p2)
    if o2 == 0:
        return on_segment(p, p2, p3)
    if o3 == 0:
        return on_segment(p, p3, p1)

    return False

def solve():
    n, triangles = read_input()

    total_perimeter = 0

    for i in range(n):
        p1, q1, p2, q2, p3, q3 = triangles[i]

        # Check if edge 1-2 is completely inside another triangle
        inside = False
        for j in range(n):
            if i == j:
                continue
            if is_point_inside_triangle((p1, q1), triangles[j]) or is_point_inside_triangle((p2, q2), triangles[j]):
                inside = True
                break

        if not inside:
            total_perimeter += edge_length((p1, q1), (p2, q2))

        # Check if edge 2-3 is completely inside another triangle
        inside = False
        for j in range(n):
            if i == j:
                continue
            if is_point_inside_triangle((p2, q2), triangles[j]) or is_point_inside_triangle((p3, q3), triangles[j]):
                inside = True
                break

        if not inside:
            total_perimeter += edge_length((p2, q2), (p3, q3))

        # Check if edge 3-1 is completely inside another triangle
        inside = False
        for j in range(n):
            if i == j:
                continue
            if is_point_inside_triangle((p3, q3), triangles[j]) or is_point_inside_triangle((p1, q1), triangles[j]):
                inside = True
                break

        if not inside:
            total_perimeter += edge_length((p3, q3), (p1, q1))

    print(total_perimeter)

solve()

