import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    n, m = int(next(it)), int(next(it))
    edges = [[] for _ in range(n + 1)]
    cycle_edges = [None] * (n + 1)
    parent = list(range(n + 1))
    rank = [1] * (n + 1)

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px == py:
            return False
        if rank[px] < rank[py]:
            px, py = py, px
        parent[py] = px
        rank[px] += rank[py]
        return True

    for _ in range(m):
        a, b = int(next(it)), int(next(it))
        edges[a].append(b)
        edges[b].append(a)

    # Find cycles using DFS
    visited = [False] * (n + 1)
    cycle_count = 0
    cycle_edge_map = {}

    def dfs(u, prev, parent_id, depth):
        visited[u] = True
        for v in edges[u]:
            if v == prev:
                continue
            if not visited[v]:
                if dfs(v, u, parent_id, depth + 1):
                    # Found cycle
                    cycle_edges[u] = cycle_count
                    cycle_edges[v] = cycle_count
                    cycle_count += 1
                    return True
                else:
                    return False
            else:
                # Found a back edge, this forms a cycle
                cycle_edges[u] = cycle_count
                cycle_edges[v] = cycle_count
                cycle_count += 1
                return True
        return False

    # Start DFS from each component
    for i in range(1, n + 1):
        if not visited[i]:
            if dfs(i, -1, -1, 0):
                pass

    # Find paths and count cycles
    output = []
    k = int(next(it))
    for _ in range(k):
        x, y = int(next(it)), int(next(it))
        if find(x) != find(y):
            output.append(1)
            continue

        # Count cycles on the path from x to y
        cycles = 0
        u = x
        while find(u) != find(x):
            u = find(u)
            cycles += 1
        v = y
        while find(v) != find(x):
            v = find(v)
            cycles += 1

        # Also check if both start and end inside cycles
        if cycle_edges[x] is not None and cycle_edges[y] is not None:
            cycles += 1

        output.append((1 << cycles) % 1000000007)

    sys.stdout.write("\n".join(map(str, output)))

if __name__ == "__main__":
    solve()
"}

