        count = [0] * n
        invited_set = {i}

        # Count messages sent by invited employees
        for j in invited_set:
            for k in range(n):
                if contacts[j][k] == '1':
                    count[k] += 1

        # Check if this configuration works
        valid = True
        for i in range(n):
            if count[i] == a[i]:
                valid = False
                break

        if valid:
            print(1)
            print(i + 1)
            return

    # Try inviting two employees at a time
    for i in range(n):
        for j in range(i + 1, n):
            invited_set = {i, j}
            count = [0] * n

            for k in invited_set:
                for l in range(n):
                    if contacts[k][l] == '1':
                        count[l] += 1

            valid = True
            for i in range(n):
                if count[i] == a[i]:
                    valid = False
                    break

            if valid:
                print(2)
                print(i + 1, j + 1)
                return

    # Try inviting three employees at a time
    for i in range(n):
