{"code": "from collections import deque

def find_path(tree, start, end):
    """Find the path from start to end using BFS."""
    parent = {}
    queue = deque([start])
    parent[start] = None

    while queue:
        node = queue.popleft()
        if node == end:
            break
        for neighbor in tree[node]:
            if neighbor not in parent:
                parent[neighbor] = node
                queue.append(neighbor)

    # Reconstruct path
    path = []
    current = end
    while current is not None:
        path.append(current)
        current = parent[current]

    return path[::-1]

def solve():
    n = int(input())
    tree = [[] for _ in range(n + 1)]

    for i in range(1, n):
        x, y = map(int, input().split())
        tree[x].append(y)
        tree[y].append(x)

    m = int(input())
    queries = []

    for i in range(m):
        a, b, g = map(int, input().split())
        queries.append((a, b, g))

    # Assign initial values
    values = [1] * (n - 1)

    for a, b, g in queries:
        # Find path from a to b
        path = find_path(tree, a, b)

        # Find all edges on this path
        edges_on_path = set()
        for i in range(len(path) - 1):
            u = path[i]
            v = path[i + 1]
            for j in range(n - 1):
                if (u == tree[j][0] and v == tree[j][1]) or \n                   (u == tree[j][1] and v == tree[j][0]):
                    edges_on_path.add(j)
                    break

        # Set all edges on this path to at least g
        for edge_id in edges_on_path:
            if values[edge_id] < g:
                values[edge_id] = g

    # Verify
    valid = True
    for a, b, g in queries:
        path = find_path(tree, a, b)
