def solve():
    n = int(input())
    a = list(map(int, input().split()))

    # If all elements are equal, impossible
    if len(set(a)) == 1:
        print("NO")
        return

    # If n == 0, impossible
    if n == 0:
        print("NO")
        return

    # If n == 1, one sequence is empty
    if n == 1:
        print("YES")
        print("0")
        print()
        print("1")
        print(a[0])
        return

    # Sort the array
    a_sorted = sorted(a)

    # Try all combinations of assigning min and max to either sequence
    for assign_min_to_inc in [True, False]:
        for assign_max_to_inc in [True, False]:
            inc = []
            dec = []

            # Assign min and max
            if assign_min_to_inc:
                inc.append(a_sorted[0])
            else:
                dec.append(a_sorted[0])

            if assign_max_to_inc:
                inc.append(a_sorted[-1])
            else:
                dec.append(a_sorted[-1])

            # Try to greedily assign remaining elements
            inc_ok = True
            dec_ok = True

            for val in a_sorted[1:-1]:
                # Try to add to inc if possible
                if inc_ok and inc[-1] < val:
                    inc.append(val)
                # Else try to add to dec if possible
                elif dec_ok and dec[-1] > val:
                    dec.append(val)
                # Else neither works
                else:
                    inc_ok = False
                    dec_ok = False

            if inc_ok and dec_ok:
                # Check if all elements are used
                if len(inc) + len(dec) != n:
                    continue

                # Check if increasing is strictly increasing
                for i in range(len(inc) - 1):
                    if inc[i] >= inc[i + 1]:
                        inc_ok = False
                        break

                # Check if decreasing is strictly decreasing
                for i in range(len(dec) - 1):
                    if dec[i] <= dec[i + 1]:
