import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    # Read initial state
    init = []
    for _ in range(n):
        row = []
        for _ in range(m):
            row.append(next(it))
        init.append(row)

    # Read final state
    final = []
    for _ in range(n):
        row = []
        for _ in range(m):
            row.append(next(it))
        final.append(row)

    ops = []

    # We'll use a specific cell as a buffer, maybe (n, m)
    hub = (n, m)

    # Move characters from initial to hub first
    for i in range(n):
        for j in range(m):
            while len(init[i][j]) > 0:
                # Move last character to hub
                # First reach the hub
                # Actually we need to check if we're already in the same row or column
                if i == n:
                    # Same row
                    if j < m:
                        # Move right
                        while j < m - 1:
                            ops.append((i + 1, j + 2, i + 1, j + 1))
                            j += 1
                    else:
                        # Already at hub
                        pass
                elif j == m:
                    # Same column
                    if i < n:
                        # Move down
                        while i < n - 1:
                            ops.append((i + 2, m, i + 1, m))
                            i += 1
                else:
                    # Move to same row first
                    if i < n:
                        while i < n - 1:
