    # The pattern of which train arrives first might repeat every max(a, b) minutes?

    for t in range(1, lcm // 10000 + 1):
        # t is in [1, lcm / 10000]
        dasha_next = t + (a - (t % a))
        masha_next = t + (b - (t % b))

        if dasha_next < masha_next:
            dasha_count += 1
        elif masha_next < dasha_next:
            masha_count += 1
        else:
            # Tie: choose the direction with less frequent trains
            if a < b:
                masha_count += 1
            else:
                dasha_count += 1

    # Multiply by the number of full patterns
    pattern_count = lcm // 10000
    dasha_count *= pattern_count
    masha_count *= pattern_count

    # Handle the remaining part of the last pattern
    for t in range(lcm // 10000 * 10000 + 1, lcm + 1):
        dasha_next = t + (a - (t % a))
        masha_next = t + (b - (t % b))

        if dasha_next < masha_next:
