import sys
from collections import deque

def solve() -> None:
    n, m, k = map(int, sys.stdin.readline().split())
    grid = []
    for i in range(n):
        row = sys.stdin.readline().strip()
        grid.append(list(row))

    # Find all lakes (connected components of '.' not on the border)
    visited = [[False] * m for _ in range(n)]
    lakes = []

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def bfs(start_i, start_j):
        queue = deque([(start_i, start_j)])
        visited[start_i][start_j] = True
        lake = []
        lake.append((start_i, start_j))

        while queue:
            ci, cj = queue.popleft()
            for di, dj in directions:
                ni, nj = ci + di, cj + dj
                if 0 <= ni < n and 0 <= nj < m and not visited[ni][nj]:
                    if grid[ni][nj] == '.':
                        visited[ni][nj] = True
                        queue.append((ni, nj))
                        lake.append((ni, nj))
        return lake

    for i in range(1, n-1):  # not on top or bottom border
        for j in range(1, m-1):  # not on left or right border
            if not visited[i][j] and grid[i][j] == '.':
                lake = bfs(i, j)
                lakes.append(lake)

    # Sort lakes by size (we want to keep largest lakes)
    lakes.sort(key=len, reverse=True)

    # If we need to keep k lakes, fill all others completely
    # We need to fill lakes of size <= (lakes[k] if k < len(lakes) else 0)
    if k < len(lakes):
        cutoff = len(lakes[k])
    else:
        cutoff = 0

    for lake in lakes:
        if len(lake) < cutoff:
            for i, j in lake:
                grid[i][j] = '*'

    # Print result
    print(len(lakes) - k)  # number of cells filled
    for row in grid:
        print(''.join(row))

if __name__ == '__main__':
    solve()
