def solve() -> None:
    word = input().strip()

    # Check if there are any typos
    vowels = {'a', 'e', 'i', 'o', 'u'}

    # Check if a sequence is a typo
    def is_typo(start: int, end: int) -> bool:
        consonants = set()
        has_vowel = False
        for i in range(start, end):
            c = word[i]
            if c in vowels:
                has_vowel = True
            else:
                consonants.add(c)

        # If there's no vowel, all are consonants (so we need to check)
        if not has_vowel:
            # Check if there are at least 3 consonants with at least 2 different
            if len(word[start:end]) >= 3:
                return len(consonants) >= 2

        return False

    # Check if the whole word has any typos
    has_typo = False
    for i in range(len(word) - 2):
        if is_typo(i, i + 3):
            has_typo = True
            break

    if not has_typo:
        print(word)
        return

    # Dynamic programming to find minimal spaces
    n = len(word)
    dp = [float('inf')] * (n + 1)
    dp[0] = 0  # 0 characters means 0 spaces

    # Try to split from left to right
    for i in range(1, n + 1):
        for j in range(i):
            # Check if substring [j, i) is a valid word
            if not is_typo(j, i):
                dp[i] = min(dp[i], dp[j] + 1)

    # Reconstruct the solution
    result = []
    i = n
    while i > 0:
        for j in range(i):
            if dp[i] == dp[j] + 1 and not is_typo(j, i):
                result.append(word[j:i])
                i = j
                break

    print(' '.join(result[::-1]))

solve()
"}

