import sys

def solve():
    data = sys.stdin.read().strip().split()
    n = int(data[0])
    p = list(map(float, data[1:]))

    # dp[i] = dictionary mapping (product, sum_ratio) to probability
    # But we can also just keep track of max probability for each state
    dp = []
    dp.append({(1.0, 0.0): 1.0})  # empty subset (product=1, sum_ratio=0, probability=0)

    for i in range(n):
        new_dp = {}
        curr = dp[-1]

        # Option 1: don't include friend i
        for (p_product, s_sum_ratio), prob in curr.items():
            if (p_product, s_sum_ratio) not in new_dp:
                new_dp[(p_product, s_sum_ratio)] = prob
            else:
                new_dp[(p_product, s_sum_ratio)] = max(new_dp[(p_product, s_sum_ratio)], prob)

        # Option 2: include friend i
        for (p_product, s_sum_ratio), prob in curr.items():
            new_p_product = p_product * (1.0 - p[i])
            new_s_sum_ratio = s_sum_ratio + p[i] / (1.0 - p[i])
            new_prob = new_p_product * new_s_sum_ratio

            if (new_p_product, new_s_sum_ratio) not in new_dp:
                new_dp[(new_p_product, new_s_sum_ratio)] = new_prob
            else:
                new_dp[(new_p_product, new_s_sum_ratio)] = max(new_dp[(new_p_product, new_s_sum_ratio)], new_prob)

        dp.append(new_dp)

    max_prob = -1.0
    final_dp = dp[-1]
    for (p_product, s_sum_ratio), prob in final_dp.items():
        if prob > max_prob:
            max_prob = prob

    print(f"{max_prob:.12f}")

