def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    return a * b // gcd(a, b)

def solve():
    cnt1, cnt2, x, y = map(int, input().split())
    lcm_xy = lcm(x, y)

    # Binary search on v
    low = 1
    high = cnt1 + cnt2 + 1
    answer = high

    while low <= high:
        mid = (low + high) // 2

        # Total distinct numbers available
        total = mid - mid // lcm_xy

        # Friend 1 needs cnt1 numbers not divisible by x
        # Friend 2 needs cnt2 numbers not divisible by y

        # Check if we have enough numbers in total
        if total >= cnt1 + cnt2:
            # Check if we have enough for each friend individually
            if mid - mid // x >= cnt1 and mid - mid // y >= cnt2:
                answer = mid
                high = mid - 1
            else:
                low = mid + 1
        else:
            low = mid + 1

    print(answer)

solve()
"}

