import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    t = int(data[idx])
    idx += 1

    results = []

    for _ in range(t):
        n = int(data[idx])
        idx += 1

        a = list(map(int, data[idx:idx+n]))
        idx += n

        # Count frequency of each element
        freq = {}
        for num in a:
            freq[num] = freq.get(num, 0) + 1

        # If all elements are the same, we can't perform any operations
        if len(freq) == 1:
            results.append(str(n))
        else:
            # Otherwise, we can reduce to n % 2
            results.append(str(n % 2))

    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
    solve()
