import sys

def solve():
    MOD = 1000000007
    line = sys.stdin.readline().strip().split()
    if not line:
        return
    n, m, k = map(int, line)

    # Each point at position (i, j) belongs to exactly (n - i + 1) * (n - j + 1) subtables

    # Let me think about it as a product of independent column choices

    # For m > n, I think the answer is: C(n * (m - n + 1), k)

    from math import factorial

    def comb(n, k):
        if k < 0 or k > n:
            return 0
        return factorial(n) // (factorial(k) * factorial(n - k))

    if m <= n:
        print(comb(m * n, k) % MOD)
    else:
        # For m > n, I think it's C(n, k) * C(m - n + 1, k)
        print(comb(n, k) % MOD * comb(m - n + 1, k) % MOD)

solve()
"}

