import sys

def solve():
    s = sys.stdin.read().strip()
    n = len(s)
    if n == 0:
        return
    # Actually n >= 1 by constraints
    # We'll process
    # Create list for output
    out = list(s)
    for i in range(1, n):
        if out[i] == out[i-1]:
            # Need to change out[i]
            # Find a character different from out[i-1] and also different from out[i+1] if exists
            # Try 'a', 'b', 'c' in order
            ch = None
            candidates = ['a', 'b', 'c']
            for c in candidates:
                if c != out[i-1]:
                    if i + 1 < n and c != out[i+1]:
                        ch = c
                        break
                    elif i + 1 >= n:
                        ch = c
                        break
            # If ch found, set it
            if ch is not None:
                out[i] = ch
            # If not found (but since we have 3 candidates and 2 forbidden, at least one is left)
            # Actually we can just pick any different from out[i-1]; even if same as out[i+1], it's fine because we'll check again at next step
            # The standard greedy is: pick first letter among 'a','b','c' that differs from both previous and next.
    print(''.join(out))

if __name__ == '__main__':
    solve()
