# Returns largest divisor <= target, or -1 if none
# We assume divisors sorted
def find_max_divisor(divisors, target):
    lo, hi = 0, len(divisors)
    while lo < hi:
        mid = (lo + hi) // 2
        if divisors[mid] <= target:
            lo = mid + 1
        else:
            hi = mid
