n = int(input())

# Build the tree
adj = [[] for _ in range(n + 1)]
for _ in range(n - 1):
    u, v = map(int, input().split())
    adj[u].append(v)
    adj[v].append(u)

# Read colors
colors = list(map(int, input().split()))

# Check if a subtree rooted at v has consistent colors
# Returns True if all descendants have the same color as v
# Returns False if mixed colors found

def is_monochromatic(v, parent, color):
    if parent is None:
        # This is the root of the tree, we don't care about its color
        pass
    else:
        # Check if this subtree has consistent color
        for child in adj[v]:
            if child == parent:
                continue
            if colors[child - 1] != color:
                return False

    # Recursively check all children
    for child in adj[v]:
        if child == parent:
            continue
        if not is_monochromatic(child, v, color):
            return False

    return True

# Find any valid root
for root in range(1, n + 1):
    # Check if all children have monochromatic subtrees
    is_valid = True

    # The root's own color doesn't matter for the whole tree
    for child in adj[root]:
        # Check if subtree rooted at child is monochromatic
        # The color should be the same as the child's color
        if not is_monochromatic(child, root, colors[child - 1]):
            is_valid = False
            break

    if is_valid:
        print("YES")
        print(root)
        exit()

print("NO")
