            # Try each remaining element to see if it fits
            # We can either go forward or backward
            for k in range(1, n-1):
                # Try to find the k-th element in AP
                # Forward: x + k*d
                # Backward: x - (k-1)*d = (x - (k-1)*d) % m
                forward = (x + k * d) % m
                backward = (x - (k-1) * d) % m

                found = False
                for val in a:
                    if val == forward:
                        found = True
                        break

                if not found:
                    for val in a:
                        if val == backward:
                            found = True
                            break

                if not found:
                    ok = False
                    break

