import sys

def solve():
    n = int(sys.stdin.readline())
    probs = list(map(float, sys.stdin.readline().split()))

    max_prob = 0.0

    # Try all possible subsets using bitmasking
    for mask in range(1, 1 << n):
        total_prob = 0.0

        # Count how many people we're asking
        count = 0
        for i in range(n):
            if (mask >> i) & 1:
                count += 1
                total_prob += probs[i]

        # Probability that exactly one of the asked people works
        # = sum of p_i * product_{j≠i} (1-p_j) for all asked i
        if count == 0:
            continue
        elif count == 1:
            prob = probs[i]  # where i is the only asked person
        else:
            # Try each person as the one who works
            prob = 0.0
            for i in range(n):
                if (mask >> i) & 1:
                    p = probs[i]
                    product = 1.0
                    for j in range(n):
                        if j != i and (mask >> j) & 1:
                            product *= (1.0 - probs[j])
                    prob += p * product

        max_prob = max(max_prob, prob)

    print(f"{max_prob:.10f}")

if __name__ == "__main__":
    solve()
