# Let's reconsider. The issue with the previous approach is that we're only adding characters with count > 2 when even.
# But there might be cases where count == 2 and the string doesn't end with c, or it ends with c but we can still have a working button.

# Actually, let's think about the problem differently. For a character c to be definitely working, it must appear an odd number of times.
# But there's also a scenario: If the string ends with c, and count[c] % 2 == 0, then the last c is the second character in the last pair.
# This means the last character c must have at least one more c before it (to form the pair). This might not always be true, but it's a constraint.

# Let's try a different approach: For each character c, if count[c] % 2 == 0 and the string ends with c, then the first occurrence of c must be at the beginning.
# This is a strong constraint that might not always hold, but it's worth trying.


def solve():
    t = int(input())
    for _ in range(t):
        s = input().strip()
        n = len(s)

        # Count occurrences
        count = {}
        for c in s:
            count[c] = count.get(c, 0) + 1

        # Determine working characters
        working = []
        for c in sorted(count.keys()):
            if count[c] % 2 == 1:
                # Appears an odd number of times, must be working
                working.append(c)
            else:
                # Appears an even number of times
                # If the string ends with c and count[c] == 2, the first c must be at the beginning
                if count[c] > 2:
                    working.append(c)
                elif count[c] == 2 and s[-1] != c:
                    working.append(c)

        print(''.join(working))

