    input = sys.stdin.read().split()
    data = iter(input)

    t = int(next(data))

    for _ in range(t):
        n = int(next(data))
        a = [int(next(data)) for _ in range(n)]

        # Process from right to left
        T = 0
        for i in range(n-1, 0, -1):
            # We need a[i] <= a[i-1]
            if a[i] > a[i-1]:
                while a[i] > a[i-1]:
                    T += 1
                    a[i-1] += 2 ** (T - 1)

