import sys

def solve():
    n = int(sys.stdin.readline())

    # Dictionary to store frequency of each bitmask
    bitmask_count = {}

    # First pass: compute bitmask for each string and store frequencies
    for _ in range(n):
        s = sys.stdin.readline().strip()

        mask = 0
        for char in s:
            mask ^= (1 << (ord(char) - ord('a')))

        if mask in bitmask_count:
            bitmask_count[mask] += 1
        else:
            bitmask_count[mask] = 1

    # Total number of palindrome pairs
    total_pairs = 0

    # For each string, compute its mask and find pairs
    for _ in range(n):
        s = sys.stdin.readline().strip()

        mask = 0
        for char in s:
            mask ^= (1 << (ord(char) - ord('a')))

        # For the current string with mask, find all previous strings that form a valid pair
        if mask in bitmask_count:
            # Count of strings with the same mask (all even counts)
            count = bitmask_count[mask]
            total_pairs += count

            # Remove this mask from the dictionary (since we already counted all pairs with this mask)
            del bitmask_count[mask]

        # Also consider pairs with different masks that together have all even counts
        # i.e., mask1 ^ mask2 == 0 (all even counts)
        if mask == 0:
            # If mask is 0, all counts are even, so any string with mask 0 can pair with this one
            pass


    print(total_pairs)

if __name__ == "__main__":
    solve()
