def solve():
    n, m, k = map(int, input().split())
    grid = []
    for _ in range(n):
        grid.append(list(input().strip()))

    # Find all lakes using DFS
    visited = [[False for _ in range(m)] for _ in range(n)]
    lakes = []  # list of (start_x, start_y, lake_cells)

    def is_ocean(x, y):
        return x == 0 or x == n-1 or y == 0 or y == m-1

    # Flood fill from the border
    def flood_from_border():
        visited = [[False for _ in range(m)] for _ in range(n)]
        stack = []

        # Mark cells connected to border as visited
        for i in range(n):
            for j in range(m):
                if is_ocean(i, j):
                    stack.append((i, j))
                    visited[i][j] = True

        while stack:
            x, y = stack.pop()
            for dx, dy in [(-1,0),(1,0),(0,-1),(0,1)]:
                nx, ny = x+dx, y+dy
                if 0 <= nx < n and 0 <= ny < m and not visited[nx][ny] and grid[nx][ny] == '.':
                    visited[nx][ny] = True
                    stack.append((nx, ny))

    flood_from_border()

    # Find all lakes
    def find_lakes():
        visited = [[False for _ in range(m)] for _ in range(n)]
        for i in range(n):
            for j in range(m):
                if not visited[i][j] and grid[i][j] == '.':
                    # It's a lake if not on border
                    if not is_ocean(i, j):
                        stack = [(i, j)]
                        visited[i][j] = True
                        lake_cells = [(i, j)]

                        while stack:
                            x, y = stack.pop()
                            for dx, dy in [(-1,0),(1,0),(0,-1),(0,1)]:
                                nx, ny = x+dx, y+dy
                                if 0 <= nx < n and 0 <= ny < m and not visited[nx][ny] and grid[nx][ny] == '.':
                                    visited[nx][ny] = True
                                    lake_cells.append((nx, ny))
                                    stack.append((nx, ny))
                        lakes.append(lake_cells)

    find_lakes()

    # We need to keep k lakes, remove others
    # Remove lakes by area (smaller lakes first)
    lakes.sort(key=len)

    # Convert to set of coordinates
    ocean_water = set()
    for i in range(n):
        for j in range(m):
            if is_ocean(i, j) and grid[i][j] == '.':
                ocean_water.add((i, j))

    # Don't change cells in ocean_water

    # Don't change cells in kept lakes
    kept_lakes = set()
    for lake in lakes[-k:]:
        for x, y in lake:
            kept_lakes.add((x, y))

    # Output
    print(len(lakes) - k)  # number of lakes removed

    for i in range(n):
        row = []
        for j in range(m):
            if (i, j) in ocean_water or (i, j) in kept_lakes:
                row.append(grid[i][j])
            else:
                row.append('*')  # transform to land
        print(''.join(row))

solve()
