import sys

def solve():
    n = int(sys.stdin.readline())

    if n == 1:
        print(0)
        return

    # Pair up the numbers to ensure at most 2 different values
    # For simplicity, we'll pair adjacent numbers
    pairs = []

    if n % 2 == 0:
        for i in range(0, n, 2):
            pairs.append((i + 1, i + 2))
    else:
        # If n is odd, pair up all but the last one
        for i in range(0, n - 1, 2):
            pairs.append((i + 1, i + 2))
        # The last element remains unpaired
        pairs.append((n, n))

    print(len(pairs))
    for x, y in pairs:
        print(x, y)

if __name__ == "__main__":
    solve()
