def solve():
    n = int(input())
    b_prime = list(map(int, input().split()))
    c_prime = list(map(int, input().split()))

    # Check if min > max for any position
    for i in range(n - 1):
        if b_prime[i] > c_prime[i]:
            print(-1)
            return

    # We'll use backtracking with pruning
    # Try different assignments of pairs to positions

    # For each position, we can assign either min or max of the corresponding pair
    # We'll build the array from left to right

    # We need to track which pairs we've used
    used = [False] * (n - 1)

    def backtrack(pos, last_val, used):
        if pos == n:
            return True

        # Try both possible values for the current position
        # pos: current position to assign
        # last_val: the value at position pos-1
        # used: which pairs we've used

        for val in [b_prime[pos-1], c_prime[pos-1]]:
            if val == last_val:
                # Same value, just propagate
                if backtrack(pos + 1, val, used):
                    return True
            else:
                # Different value, we need to check if this pair can be used
                # This pair must be used for this position
                idx = pos - 1
                if not used[idx]:
                    used[idx] = True

                    # Check if this works with the previous value
                    if (last_val == b_prime[idx] and val == c_prime[idx]) or (last_val == c_prime[idx] and val == b_prime[idx]):
                        # Valid assignment
                        if backtrack(pos + 1, val, used):
                            return True

                    # Backtrack
                    used[idx] = False

        return False

    if backtrack(1, 0, used):
        # Build the array from the backtracking
        a = [0] * n
        last = 0
        for i in range(n - 1):
            idx = i
            for val in [b_prime[i], c_prime[i]]:
                if val == last:
                    a[i] = val
                    break
            else:
                # Find the unused pair
                for j in range(n - 1):
                    if not used[j]:
                        # This pair must be used for position i
                        if j == idx:
                            a[i] = b_prime[j] if last == c_prime[j] else c_prime[j]
                        else:
                            a[i] = b_prime[j]
                        break
            last = a[i]

        print(' '.join(map(str, a)))
    else:
        print(-1)

