import sys

def is_increasing(seq):
    if len(seq) <= 1:
        return True
    return all(seq[i] < seq[i+1] for i in range(len(seq) - 1))

def is_decreasing(seq):
    if len(seq) <= 1:
        return True
    return all(seq[i] > seq[i+1] for i in range(len(seq) - 1))

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    a_sorted = sorted(a)

    # Try different assignments of elements to the increasing sequence
    for i in range(n):
        # Try to assign first i elements to increasing
        inc = a_sorted[:i]
        dec = a_sorted[i:]

        if is_increasing(inc) and is_decreasing(dec):
            # Output
            print("YES")
            print(len(inc))
            if inc:
                print(' '.join(map(str, inc)))
            else:
                print()  # empty line
            print(len(dec))
            if dec:
                print(' '.join(map(str, dec)))
            else:
                print()  # empty line
            return

    # Try assigning empty increasing sequence (all elements to decreasing)
    if is_decreasing(a_sorted):
        print("YES")
        print(0)
        print()  # empty line
        print(len(a_sorted))
        print(' '.join(map(str, a_sorted)))
        return

