import bisect

def longest_non_decreasing_subsequence(arr):
    """Find the length of the longest non-decreasing subsequence."""
    # Using a patience sorting approach
    # We maintain an array where dp[i] is the smallest last element of a non-decreasing subsequence of length i+1
    dp = []

    for x in arr:
        # Find the first element in dp that is strictly greater than x
        idx = bisect.bisect_right(dp, x)  # returns insertion point
        if idx == 0:
            # x is smaller than all elements in dp
            dp[0] = x
        elif idx == len(dp):
            # x is larger than all elements in dp
            dp.append(x)
        else:
            # Replace dp[idx] with x
            dp[idx] = x

    return len(dp)

def solve() -> None:
    n, m = map(int, input().split())
    species = []

    for _ in range(n):
        parts = input().split()
        s = int(parts[0])
        species.append(s)

    max_len = longest_non_decreasing_subsequence(species)
    print(n - max_len)

if __name__ == "__main__":
    solve()
"}

