def count_messages(S, i):
    # count how many messages employee i gets if subset S comes
    # S is a set of integers (0-indexed)
    cnt = 0
    for j in S:
        if contact[j][i] == '1':
            cnt += 1
    cnt += 1 if i in S else 0
    return cnt

# Try all subsets of employees
from itertools import combinations

def find_subset():
    # Try all subsets
    for m in range(1, n + 1):
        for subset in combinations(range(n), m):
            # Check if this subset makes Igor lose
            lost = False
            for i in range(n):
                if count_messages(set(subset), i) != a[i]:
                    lost = True
                    break
            if lost:
                return sorted(subset)
    return -1

result = find_subset()
print(len(result))
if len(result) > 0:
    print(' '.join(map(str, [x + 1 for x in result])))
else:
    print(-1)
