def gcd(x, y):
    while y:
        x, y = y, x % y
    return x

def lcm(x, y):
    return x * y // gcd(x, y)

a, b = map(int, input().split())

total_dasha = 0
total_masha = 0

# Time interval where Vasya can appear (0 < t <= LCM)
period = lcm(a, b)

dasha_times = set(range(0, period, a))
masha_times = set(range(0, period, b))

# Combine all arrival times and sort them
all_times = sorted(dasha_times.union(masha_times))

# Check intervals between each pair of consecutive times
for i in range(len(all_times) - 1):
    start = all_times[i]
    end = all_times[i + 1]

    # Determine which train arrives first in this interval
    # If start is 0 and end is the first arrival, we need to be careful
    if start == 0:
        # Vasya appears just after 0
        if end == a:
            # Next Dasha at a
            total_dasha += a
        elif end == b:
            # Next Masha at b
            total_masha += b
        else:
            # This shouldn't happen
            pass
    else:
        # In the interval (start, end), determine which train arrives first
        next_dasha = ((start // a) + 1) * a
        next_masha = ((start // b) + 1) * b

        if next_dasha < next_masha:
            total_dasha += end - start
        elif next_masha < next_dasha:
            total_masha += end - start
        else:
            # Tie, go to the girl with the larger train interval
            if a > b:
                total_dasha += end - start
            else:
                total_masha += end - start

# Also check the interval from the last arrival to period
if all_times and all_times[-1] < period:
    last_arrival = all_times[-1]
    total_dasha += period - last_arrival

if total_dasha > total_masha:
    print("Dasha")
elif total_masha > total_dasha:
    print("Masha")
else:
    print("Equal")
