n = int(input())
edges = [[] for _ in range(n + 1)]
for _ in range(n - 1):
    u, v = map(int, input().split())
    edges[u].append(v)
    edges[v].append(u)

colors = list(map(int, input().split()))

# If all colors are the same, any vertex works
if len(set(colors)) == 1:
    print("YES")
    print(1)

else:
    # Find the vertex that is the center of all different-colored vertices
    # Check if there exists a vertex v such that all vertices with a different color are only adjacent to v
    color_to_vertices = {}
    for i in range(1, n + 1):
        color_to_vertices.setdefault(colors[i - 1], []).append(i)

    # Check if there's a single vertex that connects all different-colored vertices
    for candidate in range(1, n + 1):
        # Check if this candidate is the center
        other_colors = [c for c in set(colors) if c != colors[candidate - 1]]
        if not other_colors:
            # All same color
            print("YES")
            print(candidate)
            break

        # Check if all other-colored vertices are adjacent to candidate
        connected = True
        for v in color_to_vertices[colors[candidate - 1]]:
            if v == candidate:
                continue
            if not edges[candidate] or candidate not in edges[v]:
                connected = False
                break

        if connected:
            # Check if all other-colored vertices are only connected to candidate
            ok = True
            for v in color_to_vertices[colors[candidate - 1]]:
                if v == candidate:
                    continue
                for neighbor in edges[v]:
                    if neighbor != candidate:
                        ok = False
                        break
                if not ok:
                    break

            if ok:
                print("YES")
                print(candidate)
                break
    else:
        print("NO")
