def solve() -> None:
    n = int(input())
    grid = input().strip()

    asterisks = []
    packmen = []

    for i, c in enumerate(grid):
        if c == '*':
            asterisks.append(i)
        elif c == 'P':
            packmen.append(i)

    # For each segment of consecutive asterisks, find minimum time
    # A segment is a set of consecutive asterisks between two non-asterisks or ends
    # For a segment from L to R (inclusive), we need a packman to cover it
    # Minimum time is: min over all packmen P of max(L - P, P - R) if P outside [L, R], else 0

    time = 0
    i = 0
    while i < n:
        if grid[i] == '*':
            # Find the end of the asterisk segment
            L = i
            while i < n and grid[i] == '*':
                i += 1
            R = i - 1

            # Find minimum time to cover this segment with any packman
            min_time = float('inf')
            for P in packmen:
                if L <= P <= R:
                    time_needed = 0
                else:
                    time_needed = max(L - P, P - R)
                min_time = min(min_time, time_needed)

            time = max(time, min_time)

            # Skip over the asterisks
            i += 1
        else:
            i += 1

    print(time)

solve()
