import sys
from collections import deque

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    k = int(next(it))
    grid = []
    for _ in range(n):
        grid.append(list(next(it)))

    visited = [[False] * m for _ in range(n)]
    lakes = []

    # Find all lakes
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.' and not visited[i][j] and i in (0, n-1) or j in (0, m-1):
                # Border cell, skip
                continue
            # Not border, not visited, is '.'
            queue = deque([(i, j)])
            visited[i][j] = True
            lake_area = 0
            cells = []
            while queue:
                x, y = queue.popleft()
                if grid[x][y] == '.':
                    lake_area += 1
                    cells.append((x, y))
                    for dx, dy in [(0,1),(1,0),(0,-1),(-1,0)]:
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < n and 0 <= ny < m and not visited[nx][ny] and grid[nx][ny] == '.':
                            visited[nx][ny] = True
                            queue.append((nx, ny))
            if lake_area > 0:
                lakes.append((lake_area, cells))

    L = len(lakes)

    if L == 0:
        print(0)
        for row in grid:
            print(''.join(row))
        return

    if k == L:
        print(0)
        for row in grid:
            print(''.join(row))
        return

    # Sort lakes by area ascending
    lakes.sort()

    # Eliminate L - k smallest lakes
    to_fill = lakes[:L - k]
    total = sum(area for area, _ in to_fill)

    # Fill those lakes
    for area, cells in to_fill:
        for x, y in cells:
            grid[x][y] = '*'

    print(total)
    for row in grid:
        print(''.join(row))

if __name__ == '__main__':
    solve()
