import sys

def solve() -> None:
    s = sys.stdin.readline().strip()
    n = len(s)
    if n == 0:
        return

    # vowels
    vowels = {'a', 'e', 'i', 'o', 'u'}

    # bad triplets: positions i where s[i], s[i+1], s[i+2] are consonants and at least two different
    bad_positions = [-1] * n
    for i in range(n - 2):
        if s[i] not in vowels and s[i+1] not in vowels and s[i+2] not in vowels:
            # all consonants
            if s[i] != s[i+1] or s[i] != s[i+2]:  # at least two different
                bad_positions[i] = i

    # next_bad[i] = first bad triplet position >= i (or n for none)
    next_bad = [0] * (n + 3)
    # next_bad[n] = n (no triplet)
    # compute from n-1 down
    for i in range(n - 1, -1, -1):
        if bad_positions[i] == i:
            next_bad[i] = i
        else:
            next_bad[i] = next_bad[i + 1] if (i + 1 < n + 3) else n + 1

    # Now compute DP for min number of words
    INF = 10**9
    dp = [INF] * (n + 1)
    dp[0] = 0
    parent = [-1] * (n + 1)  # parent[i] = j where we split at j

    for i in range(1, n + 1):
        for j in range(max(0, i - 3000), i):
            # check if substring s[j:i] is valid
            # valid if length < 3 or no bad triplet within
            len_sub = i - j
            if len_sub < 3:
                valid = True
            else:
                # bad triplet exists in [j, i-3]?
                # next_bad[j] <= i - 3
                # i-3 >= j
                if next_bad[j] <= i - 3:
                    valid = False
                else:
                    valid = True
            if valid:
                if dp[j] + 1 < dp[i]:
                    dp[i] = dp[j] + 1
                    parent[i] = j

    if dp[n] == INF:
        # no typos, output original
        print(s)
    else:
        # reconstruct splits
        result = []
        i = n
        while i > 0:
            j = parent[i]
            result.append(s[j:i])
            i = j
        result.reverse()
        print(' '.join(result))

if __name__ == '__main__':
    solve()
"}

