    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # Dictionary to track last occurrence of each type
    last_seen = {}  # type -> last_position (0-indexed)

    result = []  # List of segments (1-indexed)
    start = 0  # Start of current segment

    # First pass: find all segments (greedy from left to right)
    for i in range(n):
        # Check if we've seen this type before and it's within the current segment
        if a[i] in last_seen and last_seen[a[i]] > start:
            # End the current segment at i
            result.append((start + 1, i + 1))  # Convert to 1-indexed
            start = i + 1  # Start new segment

        # Update last seen for this type
        last_seen[a[i]] = i

    # Second pass: refine by checking if we can extend segments backwards
    refined_result = []
    # Work from right to left
    for i in range(n - 1, -1, -1):
        if not refined_result:
            start = i
        else:
            start = refined_result[-1][0] - 1  # Start of previous segment

        # Find the farthest right position where we can end a segment
        end = i
        while end > start:
            if a[end] in last_seen and last_seen[a[end]] >= start:
                # We can end the segment at end
                refined_result.append((start + 1, end + 1))
                start = end + 1
                end = i  # Restart search
            else:
                end -= 1

    # Convert to Python-style list
    refined_result.reverse()

    if not refined_result:
        # No segments found, check if all elements are unique (can't form any good segment)
        if len(set(a)) == n:
