import re

n = int(input())
forbidden = [input().strip() for _ in range(n)]
w = input().strip()
letter = input().strip().lower()

# Find all positions covered by forbidden substrings
covered = [False] * len(w)

for sub in forbidden:
    # Find all case-insensitive matches
    matches = re.finditer(sub, w, flags=re.IGNORECASE)
    for match in matches:
        l, r = match.start(), match.end()
        # Mark all positions from l to r-1 (since Python slice is [start, end))
        for i in range(l, r):
            covered[i] = True

# Build the result
result = []
for i in range(len(w)):
    if covered[i]:
        original = w[i]
        if original.islower():
            # Lowercase: choose either letter (lowercase) or 'a'
            if letter == original:
                result.append('a')  # same case, lexicographically smaller
            else:
                result.append(letter)  # different, use lucky letter
        else:
            # Uppercase: choose either letter (uppercase) or 'A'
            if letter == original.lower():
                result.append('A')  # same case, lexicographically smaller
            else:
                result.append(letter.upper())  # different, use lucky letter
    else:
        result.append(w[i])

print(''.join(result))
