import sys
from collections import defaultdict

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    m = int(data[0])
    n = int(data[1])
    a = list(map(int, data[2:2+n]))

    # If n <= 2, any sequence is an arithmetic progression
    if n <= 2:
        print(a[0], a[1] - a[0])
        return

    # For n > 2, we need a more complex solution
    # We'll use a frequency map
    freq = defaultdict(int)
    for num in a:
        freq[num] += 1

    # Try all pairs as potential starting elements and differences
    for x in a:
        for y in a:
            if x == y:
                continue

            # Try both directions: x -> y and y -> x
            for dx in [y - x, x - y]:
                # Check if this difference works
                seen = 0
                for k in range(n):
                    val = (x + k * dx) % m
                    seen += 1 if val in freq else 0

                if seen == n:
                    print(x, dx)
                    return

    # If no valid progression found
    print(-1)

if __name__ == "__main__":
    solve()
"}

